let searchHistoryCache;
let catalog, movies=[], heroIndex=1, heroTimer, listState={}, currentMovie=null, episode=1, localVideo=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k)=>{try{return JSON.parse(localStorage.getItem('sa-'+k)||'[]')}catch{return []}};
const save=(k,v)=>localStorage.setItem('sa-'+k,JSON.stringify(v));
const catIds={'全部分类':'','电影':'13','连续剧':'12','综艺':'11','短剧':'16','动漫':'14','纪录片':'15'};
const listUrl=(cat='')=>'/movie/list?cat_id='+(catIds[cat]||cat)+'&position=movie';
const movieUrl=m=>'/movie/detail/'+(m.slug||m.id)+'-'+m.id;
function toast(s){$('#toast').classList.remove('feedback-success');$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3000)}
function categoryMenu(){return Object.keys(catIds).map(c=>{const tags=[...new Set(movies.filter(m=>!catIds[c]||m.category===c).flatMap(m=>m.tags?.map(t=>t.name)||[]))];const links=c==='全部分类'?Object.keys(catIds).filter(x=>catIds[x]).map(x=>[x,listUrl(x)]):tags.map(t=>[t,listUrl(c)+'&tag='+encodeURIComponent(t)]);return `<div class="nav-category"><a class="nav-category-link" href="${listUrl(c)}">${c}<span aria-hidden="true">›</span></a><section class="nav-submenu" aria-label="${c}二级菜单"><div class="nav-submenu-heading">${c}<a href="${listUrl(c)}">查看全部 ›</a></div><div class="nav-submenu-links">${links.map(([label,url])=>`<a href="${esc(url)}">${esc(label)}</a>`).join('')||`<a href="${listUrl(c)}">全部${c}</a>`}</div></section></div>`}).join('')}
function header(home=false){$('#header').className=home?'home-header':'';$('#header').innerHTML=`<div class="header-inner"><a class="logo" href="/" aria-label="SA影视首页"><img src="${catalog.logo}" alt="SA影视"></a><div class="nav-dropdown"><button class="nav-trigger" data-action="menu">影视⌄</button><nav class="dropdown">${categoryMenu()}<a href="/mine/help">帮助中心</a></nav></div><a class="rank-link" href="/movie/rank">排行榜</a><button class="vip" data-action="vip" aria-label="VIP会员"><img class="vip-static" src="/vip-gift.png" width="56" height="56" alt=""><img class="vip-animated" src="/vip-gift-animated.gif" width="56" height="56" alt="" aria-hidden="true"></button><nav class="mobile-nav"><a href="/">主页</a>${['电影','连续剧','综艺','动漫'].map(c=>`<a href="${listUrl(c)}">${c==='连续剧'?'电视剧':c}</a>`).join('')}</nav><form class="search-form" role="search"><input name="q" aria-label="搜索影片" placeholder="搜索您想看的影片" autocomplete="off"><button aria-label="搜索" type="submit">⌕</button><div class="search-suggest">${searchDrawer()}</div></form><div class="header-end"><div class="history-menu"><button class="history" data-action="history" type="button" aria-expanded="false" aria-controls="history-drawer"><img class="history-icon" src="/file-eye-02.svg" width="24" height="24" alt="" aria-hidden="true">看过</button><section class="history-drawer" id="history-drawer" aria-label="最近观看" hidden></section></div><button class="login-pill login-sparkle ${demoAccount?'is-authenticated':''}" data-action="login" type="button"><span class="dots_border" aria-hidden="true"></span><svg class="sparkle" width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><path class="path" d="M12 2 14.8 9.2 22 12 14.8 14.8 12 22 9.2 14.8 2 12 9.2 9.2Z"/><path class="path" d="m20 1 1 2 2 1-2 1-1 2-1-2-2-1 2-1Z"/></svg><span class="text_button">${demoAccount?'个人中心':'登录'}</span></button></div></div>`;
$('#footer').innerHTML=`<div class="footer-inner"><div><a class="logo" href="/"><img src="${catalog.logo}" alt="SA影视"></a><p>Copyright © 2018 https://samh.tw All rights reserved</p><p>SA影视参考页面复刻</p></div><div><h3>关于</h3><a href="/mine/help">关于我们</a><a href="/mine/help">联系我们</a><a href="/mine/history">观看记录</a></div><div><h3>政策</h3><a href="/mine/help">使用条款</a><a href="/mine/help">滥用报告</a><a href="/mine/help">隐私政策</a></div><div><h3>其他</h3><a href="/mine/help">常见问题</a><a href="/mine/favorites">我的收藏</a><a href="${listUrl()}">全部影片</a></div></div><div class="footer-bottom">影片信息来自参考站公开页面 · 浏览与收藏记录仅保存在本机</div>`}
function contentTags(m,limit=3){const labels=[...new Set((m.tags||[]).map(t=>t.name).filter(Boolean).concat(m.category||[]))];return `<span class="content-tags" aria-label="内容标签">${labels.slice(0,limit).map(label=>`<span class="content-tag">${esc(label)}</span>`).join('')}</span>`}
function card(m){return `<article class="movie-card"><a href="${movieUrl(m)}" aria-label="查看${esc(m.name)}"><div class="poster"><img src="${m.img}" alt="${esc(m.name)}" loading="lazy" decoding="async"><span class="score">${esc(m.score)}</span><span class="duration">${esc(m.duration)}</span><span class="hover-play" aria-hidden="true">▶</span></div><span class="card-title">${esc(m.name)}</span></a><div class="hover-info"><a class="hover-cover" href="${movieUrl(m)}" aria-label="查看${esc(m.name)}详情"><img src="${m.img}" alt="${esc(m.name)}" loading="lazy"></a><div class="hover-info-copy"><h3>${esc(m.name)}</h3><p>${contentTags(m)}　${esc(m.issue_year||m.issue_date?.slice(0,4)||'')}</p><p class="synopsis">${esc(m.description||'暂无简介')}</p><div><button data-fav="${m.id}">☆ 收藏</button><a href="${movieUrl(m)}">详情 ›</a></div></div></div><p class="card-meta">${contentTags(m)}</p></article>`}
function section(s,i,feature=false){return `<section class="${feature?'feature-section':'catalog-section'}"><div class="section-title">${s.icon?`<img src="${s.icon}" alt="">`:''}<h2>${esc(s.name)}</h2>${feature?'':`<a class="more" href="${listUrl(s.items[0]?.category)}">更多 ›</a>`}</div><div class="${feature?'feature-track':'movie-grid'}" id="row-${i}">${s.items.map(card).join('')}</div>${feature?`<button class="row-arrow prev" data-row="${i}" data-step="-1" aria-label="上一张">‹</button><button class="row-arrow next" data-row="${i}" data-step="1" aria-label="下一张">›</button>`:''}</section>`}
function home(){header(true);const b=catalog.banners[heroIndex];$('#app').innerHTML=`<section class="hero" aria-label="推荐影片轮播"><a id="hero-link" href="${bannerLink(b)}"><img class="hero-image" src="${b.content}" alt="${esc(b.name)}" fetchpriority="high"></a><div class="hero-copy" aria-live="off">${heroCopy(b)}</div><div class="hero-picker"><button class="hero-arrow" data-hero-step="-1" aria-label="上一部推荐影片">‹</button><div class="hero-thumbs" aria-label="选择推荐影片">${catalog.banners.map((x,i)=>`<button class="hero-thumb ${i===heroIndex?'active':''}" aria-pressed="${i===heroIndex}" aria-label="切换到${esc(x.name)}" data-slide="${i}"><span class="hero-poster"><img src="${bannerMovie(x)?.img||x.content}" alt="" loading="lazy"></span><span class="hero-caption">${esc(x.name)}</span></button>`).join('')}</div><button class="hero-arrow" data-hero-step="1" aria-label="下一部推荐影片">›</button></div></section><nav class="hero-nav"><div class="categories">${catalog.categories.map(c=>`<a href="${listUrl(c.name)}">${c.name}</a>`).join('')}<a href="${listUrl()}">更多</a></div><span class="theme-label">▦ 推荐主题</span><div class="theme-links">${catalog.themes.map(t=>`<a href="/theme-detail/${t.id}">${esc(t.name)} ›</a>`).join('')}</div></nav><div class="mobile-only mobile-categories">${catalog.categories.map(c=>`<a href="${listUrl(c.name)}">${c.name}</a>`).join('')}</div><div class="home-content">${catalog.home_recommends.map((s,i)=>section(s,i,true)).join('')}${catalog.sections.map((s,i)=>section(s,i+3)).join('')}</div>`;
if(!matchMedia('(prefers-reduced-motion: reduce)').matches)heroTimer=setInterval(()=>{const hero=$('.hero');if(hero&&!hero.matches(':hover')&&!hero.contains(document.activeElement)&&!document.hidden)slide(heroIndex+1)},7000);
}
function bannerLink(b){if(b.link.startsWith('/movie/detail/')){const m=movies.find(m=>b.link.endsWith(m.id));if(m)return movieUrl(m);return '/search?q='+encodeURIComponent(b.name)}return b.link.startsWith('/movie/list')?b.link:listUrl('动漫')}
function bannerMovie(b){return movies.find(m=>b.link.endsWith(m.id))}
function heroCopy(b){const m=bannerMovie(b);const facts=m?[m.score&&m.score!=='0.0'?`★ ${m.score} 分`:null,m.heat?`热度 ${m.heat}`:null,m.duration].filter(Boolean):[];const meta=m?[m.actor?.split(/[,，、/]/).slice(0,2).join('　'),''].filter(Boolean).join('　'):'';return `<h1>${esc(b.name)}</h1>${facts.length?`<div class="hero-facts">${facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`:''}${m?`<p class="hero-meta">${esc(meta)} ${contentTags(m,Infinity)}</p>`:''}<p class="hero-tagline">${esc(b.tag_text||m?.description||b.description||'精选影片，精彩呈现')}</p><a class="play-button" href="${bannerLink(b)}"><span aria-hidden="true">▶</span>立即播放</a>`}
function slide(i){heroIndex=(i+catalog.banners.length)%catalog.banners.length;const b=catalog.banners[heroIndex];if(!$('.hero'))return;$('.hero-image').src=b.content;$('.hero-image').alt=b.name;$('#hero-link').href=bannerLink(b);$('.hero-copy').innerHTML=heroCopy(b);document.querySelectorAll('[data-slide]').forEach(e=>{const active=+e.dataset.slide===heroIndex;e.classList.toggle('active',active);e.setAttribute('aria-pressed',String(active));if(active){const rail=$('.hero-thumbs');if(e.offsetLeft<rail.scrollLeft||e.offsetLeft+e.offsetWidth>rail.scrollLeft+rail.clientWidth)rail.scrollTo({left:e.offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}})}
function route(){clearInterval(heroTimer);if(localVideo){URL.revokeObjectURL(localVideo);localVideo=null;}const path=location.pathname;currentMovie=null;document.title='SA影视 - 电影电视剧动漫综艺';if(path==='/')home();else{header();if(path.startsWith('/movie/detail/'))detail(path);else if(path==='/movie/rank')rank();else if(path.startsWith('/theme-detail/'))themePage(path);else if(path==='/search'||path==='/movie/list')listing();else if(path.startsWith('/mine/'))mine(path);else $('#app').innerHTML='<div class="empty"><h1>页面不存在</h1><p>这个链接暂时没有对应内容。</p><a class="primary" href="/">返回首页</a></div>';}document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.opacity='.25';img.alt='图片暂时无法加载'},{once:true}))}
function openModal(body){const d=$('#modal');d.innerHTML='<button class="close-modal" aria-label="关闭" data-action="close">×</button>'+body;if(!d.open)d.showModal()}
let demoAccount='';
const demoRegisteredAccounts=new Set();
function registrationErrors(account,password,confirm){return {account:!/^[A-Za-z0-9]{4,10}$/.test(account)?'账号4–10位，仅限英文、数字或组合；':demoRegisteredAccounts.has(account.toLowerCase())?'该账号已被注册，请更换；':'',password:!/^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9]).{6,8}$/.test(password)?'密码6–8位，包含大小写字母和数字；':'',confirm:!confirm?'请再次输入密码；':confirm!==password?'两次输入的密码不一致':''}}
function authFieldError(name){return `<p id="auth-${name}-error" class="auth-field-error" aria-live="polite" hidden></p>`}
function login(mode='login'){if(demoAccount&&mode==='login'){navigate('/mine/favorites');return}const register=mode==='register';openModal(`<section class="auth-panel" aria-labelledby="auth-title"><div class="auth-heading"><img class="auth-logo" src="${esc(catalog.logo)}" alt="SA影视"><h2 id="auth-title">${register?'注册账号':'欢迎登录'}</h2><p>${register?'创建账号，开启您的观影时光':'欢迎回来，请登录您的账号'}</p></div><form id="login-form" data-mode="${mode}"><label for="auth-account">账号</label><input id="auth-account" name="account" autocomplete="username" placeholder="${register?'账号4–10位、仅限英文、数字或组合':'请输入账号'}" required maxlength="40">${register?authFieldError('account'):''}<label for="auth-password">密码</label><div class="auth-password"><input id="auth-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'密码6–8位，包含大小写字母和数字':'请输入密码（至少6位）'}" required minlength="6" maxlength="128"><button type="button" class="password-toggle" data-password-toggle="auth-password" aria-label="显示密码" aria-pressed="false">${passwordEye(false)}</button></div>${register?authFieldError('password'):''}${register?`<label for="auth-confirm">确认密码</label><div class="auth-password"><input id="auth-confirm" name="confirm" type="password" autocomplete="new-password" placeholder="请再次输入密码" required minlength="6" maxlength="128"><button type="button" class="password-toggle" data-password-toggle="auth-confirm" aria-label="显示确认密码" aria-pressed="false">${passwordEye(false)}</button></div>${authFieldError('confirm')}`:''}<p class="auth-switch">${register?'已有账号？':'还没有账号？'} <button type="button" data-auth-mode="${register?'login':'register'}">${register?'立即登录':'立即注册'}</button></p><p class="error" id="login-error" role="alert" hidden></p><button type="submit" class="primary auth-submit" disabled>${register?'注册':'登录'}</button></form></section>`)}
function passwordEye(visible){return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>${visible?'':'<path d="M3 3l18 18"/>'}</svg>`}
function syncAuthForm(form){const account=form.querySelector('[name=account]'),password=form.querySelector('[name=password]'),confirm=form.querySelector('[name=confirm]');if(form.dataset.mode==='register'){const errors=registrationErrors(account.value,password.value,confirm.value);for(const input of [account,password,confirm]){const message=errors[input.name],show=input.dataset.touched==='true'&&!!message;const error=form.querySelector('#auth-'+input.name+'-error');error.textContent=show?message:'';error.hidden=!show;input.setAttribute('aria-invalid',String(show));input.setAttribute('aria-describedby',error.id);input.setCustomValidity(message)}form.querySelector('.auth-submit').disabled=form.dataset.busy==='true'||Object.values(errors).some(Boolean)}else{form.querySelector('.auth-submit').disabled=!account.value.trim()||password.value.length<6||!password.value.trim()}form.querySelector('#login-error').hidden=true;}
document.addEventListener('focusout',e=>{if(e.target.matches('#login-form input')){e.target.dataset.touched='true';syncAuthForm(e.target.closest('form'))}});
document.addEventListener('input',e=>{if(e.target.matches('#login-form input')){e.target.dataset.touched='true';syncAuthForm(e.target.closest('form'))}});
document.addEventListener('click',e=>{const mode=e.target.closest('[data-auth-mode]');if(mode){login(mode.dataset.authMode);return}const b=e.target.closest('[data-password-toggle]');if(!b)return;const input=document.getElementById(b.dataset.passwordToggle),visible=input.type==='password';input.type=visible?'text':'password';b.setAttribute('aria-pressed',String(visible));b.setAttribute('aria-label',(visible?'隐藏':'显示')+(input.name==='confirm'?'确认密码':'密码'));b.innerHTML=passwordEye(visible);input.focus();});

function listing(){const p=new URLSearchParams(location.search);listState={cat:p.get('cat_id')?.split(',')[0]||'',tag:p.get('tag')||'',area:p.get('area')||'',language:p.get('language')||'',year:p.get('year')||'',status:p.get('status')||'',sort:p.get('sort')||'',q:p.get('q')||'',page:Math.max(1,+(p.get('page')||1))};renderListing()}
function filterRow(label,key,values){return `<div class="filter-row"><span class="filter-label">${label}</span><div class="filter-options">${values.map(([label,value])=>`<button data-filter="${key}" data-value="${esc(value)}" aria-pressed="${listState[key]===value}" class="${listState[key]===value?'selected':''}">${label}</button>`).join('')}</div></div>`}
function searchDemoMovie(m,i){return {...m,id:m.id+'demo'+i,slug:'search-demo',name:m.name+' · 演示'+String(i).padStart(2,'0')}}
function renderListing(){const s=listState,isSearch=location.pathname==='/search',pageSize=isSearch?28:32;const matches=isSearch&&s.q?movies.filter(m=>[m.name,m.actor,m.director].some(v=>v?.toLowerCase().includes(s.q.toLowerCase()))):[];const demos=matches.length&&matches.length<36?Array.from({length:36-matches.length},(_,i)=>searchDemoMovie(matches[i%matches.length],i+1)):[];let result=movies.concat(demos).filter(m=>(!s.cat||catIds[m.category]===s.cat)&&(!s.q||[m.name,m.actor,m.director].some(v=>v?.toLowerCase().includes(s.q.toLowerCase())))&&(!s.tag||m.tags?.some(t=>t.name===s.tag))&&(!s.area||m.area===s.area)&&(!s.language||m.language===s.language)&&(!s.status||(s.status==='全集'?m.duration.startsWith('全'):m.duration.startsWith('更新')))&&(!s.year||(s.year==='更早'?+(m.issue_year||m.issue_date?.slice(0,4))<2025:(m.issue_year||m.issue_date?.slice(0,4))===s.year)));
if(s.sort==='评分高低')result.sort((a,b)=>+b.score-+a.score);else if(s.sort==='人气高低')result.sort((a,b)=>parseFloat(b.heat||0)-parseFloat(a.heat||0));else if(s.sort==='上映时间')result.sort((a,b)=>(b.issue_date||'').localeCompare(a.issue_date||''));
const theme=catalog.themes.find(t=>location.pathname.endsWith(t.id));let title=s.q?`“${esc(s.q)}”的搜索结果`:theme?esc(theme.name):Object.keys(catIds).find(c=>catIds[c]===s.cat)||'全部影片';if(theme){const n=catalog.themes.indexOf(theme);result=movies.filter(m=>n===2?m.category==='短剧':n===3?m.category==='动漫':n===6?/悬疑|惊悚|犯罪/.test(m.tags?.map(t=>t.name).join('')):m.category==='连续剧');}
const tags=[...new Set(movies.filter(m=>!s.cat||catIds[m.category]===s.cat).flatMap(m=>m.tags?.map(t=>t.name)||[]))];const pages=Math.max(1,Math.ceil(result.length/pageSize));s.page=Math.min(s.page,pages);
$('#app').innerHTML=`<div class="page listing-page ${isSearch?'search-results-page':''}"><h1 class="${s.q?'':'sr-only'}">${title}</h1>${theme?'':`<div class="list-top"><div class="filter-panel">${filterRow('分类','cat',Object.entries(catIds).map(([label,value])=>[value?label:'全部',value]))}${filterRow('类型','tag',[['全部',''],...tags.map(t=>[t,t])])}${filterRow('地区','area',[['全部',''],...['内地剧','美剧','日剧','韩剧','港剧','泰剧','台剧'].map(t=>[t,t])])}${filterRow('语言','language',[['全部',''],...['国语','英语','日语','韩语','粤语'].map(t=>[t,t])])}${filterRow('年份','year',[['全部',''],['今年','2026'],['去年','2025'],['更早','更早']])}${filterRow('状态','status',[['全部',''],['全集','全集'],['连载','连载']])}</div></div>`}<div class="results-bar"><div class="sort-options">${['','上映时间','人气高低','评分高低'].map(x=>`<button class="${s.sort===x?'selected':''}" data-filter="sort" data-value="${x}">${x||'全部'}</button>`).join('')}</div><p class="muted">共有 ${result.length} 个筛选结果</p></div>${demos.length?'<p class="search-demo-note">含演示数据，用于预览筛选与分页效果</p>':''}<div class="movie-grid">${result.slice((s.page-1)*pageSize,s.page*pageSize).map(card).join('')||(location.pathname==='/search'?'<div class="rank-empty search-empty" role="status"><img src="/assets/search-empty.png" alt=""><p>阿偶，没有找到您想要的内容哦~</p><button class="primary" data-action="reset-filters">清除筛选</button></div>':'<div class="empty"><h2>暂无符合条件的影片</h2><p>试试其他关键词，或清除筛选条件。</p><button class="primary" data-action="reset-filters">清除筛选</button></div>')}</div>${pages>1?`<nav class="pagination" aria-label="分页">${isSearch?`<span class="rank-page-summary">共 ${result.length} 条 · 每页 ${pageSize} 条</span>`:''}<button data-page="${s.page-1}" ${s.page===1?'disabled':''}>上一页</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${s.page===i+1?'selected':''}">${i+1}</button>`).join('')}<button data-page="${s.page+1}" ${s.page===pages?'disabled':''}>下一页</button></nav>`:''}</div>`;if(s.q)$('[name=q]').value=s.q;document.title=title.replace(/&[^;]+;/g,'')+' - SA影视';}
function episodeCount(m){return m.id==='33f5fd0e81a046a0'?32:+(m.duration.match(/\d+/)?.[0]||1)}
function detail(path){const id=path.split('-').pop();const base=movies.find(m=>id.startsWith(m.id+'demo'));const m=movies.find(m=>m.id===id)||(base?searchDemoMovie(base,Number(id.slice((base.id+'demo').length))):null);if(!m){$('#app').innerHTML='<div class="empty"><h1>暂未收录这部影片</h1><p>可返回片库浏览已收录影片。</p><a class="primary" href="/movie/list">浏览片库</a></div>';return}currentMovie=m;episode=Math.max(1,+(new URLSearchParams(location.search).get('episode')||1));const hist=read('history').filter(x=>x.id!==m.id);hist.unshift({id:m.id,episode,date:new Date().toISOString()});save('history',hist.slice(0,80));document.title=m.name+' - SA影视';const count=episodeCount(m);$('#app').innerHTML=`<div class="page detail-page"><div class="detail-layout"><div class="detail-main"><div class="playback-panel"><div class="player" id="player"><img class="player-poster" src="${m.img}" alt=""><div class="player-title"><a href="/">‹</a><img src="${catalog.logo}" alt="SA FILM"><span>${esc(m.name)} · 第${episode}集</span></div><div class="player-message"><button class="primary" data-action="play">▶ 播放第${episode}集</button></div>${playerControls()}</div><div class="action-bar">${likeButton(m)}<button data-action="dislike" aria-label="踩" title="踩"><span class="dislike-icon" aria-hidden="true"></span><span>踩</span></button>${favoriteButton(m)}<button data-action="share"><span class="share-icon" aria-hidden="true"></span><span>分享</span></button><button data-action="线路" aria-haspopup="dialog"><span class="line-icon" aria-hidden="true"></span><span class="line-label">线路 ${selectedLine}</span></button><button data-action="feedback"><span class="feedback-icon" aria-hidden="true"></span><span>反馈</span></button></div></div><section class="detail-info"><h1>${esc(m.name)}</h1><p class="detail-meta">${contentTags(m,Infinity)}　 |　热度 ${esc(m.heat||'暂无数据')}　 |　${esc(m.score)} 分</p><div class="detail-description"><img src="${m.img}" alt="${esc(m.name)}"><div><p><b>上映：</b>${esc(m.issue_date||m.issue_year||'暂无数据')}</p><p><b>导演：</b>${esc(m.director||'暂无数据')}</p><p class="detail-cast"><b>主演：</b>${esc(m.actor||'暂无数据')}</p><p class="description"><b>简介：</b>${esc(m.description||'当前暂无简介')}</p><button data-action="expand-description">展开简介⌄</button></div></div></section><section class="episodes" id="episodes"><div class="episodes-head"><h2>选集</h2><button data-action="reverse-episodes">倒序 ↓</button></div><div class="episode-grid" id="episode-grid">${Array.from({length:count},(_,i)=>`<button class="${i+1===episode?'selected':''}" data-episode="${i+1}">第${i+1}集</button>`).join('')}</div><button class="episodes-toggle" data-action="toggle-episodes" aria-expanded="false" aria-controls="episode-grid">展开全部 ⌄</button></section><section class="catalog-section"><div class="section-title"><h2>推荐视频</h2></div><div class="movie-grid">${movies.filter(x=>x.category===m.category&&x.id!==m.id).slice(0,16).map(card).join('')}</div></section></div><aside class="related"><div class="detail-ad" aria-label="广告位"><span class="detail-ad-label">广告</span><img class="detail-ad-image" src="/assets/detail-ad.png" alt="Gate Exchange 广告" loading="lazy"></div><h3>相关内容</h3>${movies.filter(x=>x.category===m.category&&x.id!==m.id).slice(0,9).map(x=>`<a class="related-card" href="${movieUrl(x)}"><img src="${x.img}" alt="${esc(x.name)}"><div class="copy"><h4>${esc(x.name)}</h4><p class="muted">${contentTags(x)}</p><span>${esc(x.score)}分　${esc(x.heat||'')}</span></div></a>`).join('')}</aside></div></div>`;}
let rankState={cat:'电影',period:'year',page:1};
function periodHeat(m,period){const raw=String(m.heat||'0'),base=(parseFloat(raw)||0)*(/[w万]/i.test(raw)?10000:1);let hash=0;for(const c of String(m.id))hash=(hash*31+c.charCodeAt(0))>>>0;const month=base*(.06+(hash%120)/1000);return Math.round(period==='year'?base:period==='month'?month:month*(.08+(hash%240)/1000))}
function rank(cat=rankState.cat,period=rankState.period,page=1){const result=(new URLSearchParams(location.search).get('preview')==='empty'?[]:movies).filter(m=>m.category===cat).sort((a,b)=>periodHeat(b,period)-periodHeat(a,period));const pages=Math.max(1,Math.ceil(result.length/30));page=Math.max(1,Math.min(pages,Math.floor(Number(page))||1));rankState={cat,period,page};const offset=(page-1)*30,rows=result.slice(offset,offset+30);$('#app').innerHTML=`<section class="rank-banner" aria-labelledby="rank-heading"><img src="/assets/rank-cinema-banner.png" width="2172" height="330" alt="" fetchpriority="high"><div class="rank-banner-inner"><h1 id="rank-heading">排行榜</h1></div></section><div class="page rank-page"><div class="rank-filters"><div class="rank-tabs" role="group" aria-label="影片分类">${['电影','连续剧','综艺','短剧','动漫'].map(c=>`<button data-rank="${c}" aria-pressed="${cat===c}" class="${cat===c?'selected':''}">${c}</button>`).join('')}</div><div class="rank-periods" role="group" aria-label="排行周期">${[['year','年榜'],['month','月榜'],['week','周榜']].map(([value,label])=>`<button type="button" data-rank-period="${value}" aria-pressed="${period===value}" class="${period===value?'selected':''}">${label}</button>`).join('')}</div></div><p class="rank-data-note">周期热度为演示数据</p><div class="rank-grid">${rows.map((m,i)=>`<a href="${movieUrl(m)}" class="rank-item"><span class="rank-number">${offset+i+1}</span><img src="${m.img}" alt="${esc(m.name)}"><div><h3>${esc(m.name)}</h3><span class="score" style="position:static">${esc(m.score)} 分</span><div class="rank-content-tags">${contentTags(m)}</div><p>${{year:'年',month:'月',week:'周'}[period]}热度 ${periodHeat(m,period).toLocaleString('zh-CN')}</p></div></a>`).join('')||'<div class="rank-empty" role="status"><img src="/assets/rank-empty.png" width="1536" height="1024" alt=""><p>阿偶，没有找到您想要的内容哦~</p></div>'}</div>${result.length?`<nav class="pagination rank-pagination" aria-label="排行榜分页"><span class="rank-page-summary">共 ${result.length} 条 · 每页 30 条</span><button type="button" data-rank-page="${page-1}" ${page===1?'disabled':''}>上一页</button>${Array.from({length:pages},(_,i)=>`<button type="button" data-rank-page="${i+1}" class="${page===i+1?'selected':''}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button type="button" data-rank-page="${page+1}" ${page===pages?'disabled':''}>下一页</button></nav>`:''}</div>`}
function mine(path){if(path==='/mine/help'){$('#app').innerHTML=`<div class="page help"><h1>帮助中心</h1>${[['如何寻找影片？','通过顶部搜索框输入片名或演员，在分类页按类型、地区、年份筛选，也可以浏览排行榜。'],['为什么影片无法播放？','当前页面是界面复刻，尚未接入可用的授权播放源。播放器支持选择本机视频进行播放，视频不会上传。'],['收藏和观看记录保存在哪里？','收藏和浏览记录仅保存在当前浏览器中，清除浏览器数据后会消失。'],['可以使用原站账号登录吗？','不能。此页面没有连接原站账号服务，不会提交或保存你输入的账号密码。'],['隐私与反馈','本页面的搜索、收藏与观看记录仅在本机处理。反馈功能展示表单，但不会向原站发送信息。']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;return}const history=path==='/mine/history';const ids=history?read('history').map(x=>x.id):read('favorites');const selected=ids.map(id=>movies.find(m=>m.id===id)).filter(Boolean);$('#app').innerHTML=`<div class="page"><section class="account-summary"><div class="account-avatar" aria-hidden="true">${esc((demoAccount||'访').slice(0,1).toUpperCase())}</div><div class="account-copy"><h1>个人中心</h1><p>${esc(demoAccount||'访客')}，欢迎回来</p></div>${demoAccount?'<button class="account-logout" type="button" data-auth-logout>退出登录</button>':'<button class="primary" data-action="login">登录账号</button>'}</section><nav class="collection-tabs"><a href="/mine/favorites" class="${history?'':'selected'}">我的收藏</a><a href="/mine/history" class="${history?'selected':''}">观看记录</a></nav>${history&&selected.length?'<button class="more" data-action="clear-history">清空观看记录</button>':''}<div class="movie-grid" style="margin-top:24px">${selected.map(card).join('')||`<div class="empty"><h2>暂无${history?'观看记录':'收藏'}</h2><p>${history?'浏览影片详情后会在这里显示。':'在影片详情页点击收藏，将喜欢的影片保存在这里。'}</p><a class="primary" href="/">去发现影片</a></div>`}</div></div>`}
function navigate(url){if(url.startsWith('/search?'))rememberSearch(new URLSearchParams(url.split('?')[1]).get('q'));history.pushState({},'',url);route();window.scrollTo({top:0,behavior:'instant'})}
function updateFilter(){const p=new URLSearchParams();Object.entries(listState).forEach(([k,v])=>{if(v)p.set(k==='cat'?'cat_id':k,String(v))});history.replaceState({},'',location.pathname+'?'+p);renderListing()}
function setEpisode(n){if(!currentMovie)return;const count=episodeCount(currentMovie);if(n<1||n>count){toast(n<1?'已经是第一集':'已经是最后一集');return}navigate(movieUrl(currentMovie)+'?episode='+n)}
function play(){const v=$('video');if(v){v.paused?v.play():v.pause();return}$('.player-message').innerHTML=`<h2>暂未接入播放源</h2><p>第 ${episode} 集的影片播放地址尚未配置。<br>可选择本机视频体验播放器，文件不会上传。</p><label class="local-file">选择本机视频<input type="file" accept="video/*" id="local-video"></label>`}
let selectedLine=1;
const actions={线路:()=>openModal(`<h2>选择播放线路</h2><div class="line-options">${[1,2,3].map(n=>`<button data-line="${n}" aria-pressed="${selectedLine===n}" class="${selectedLine===n?'selected':''}">线路 ${n}<span>${selectedLine===n?'当前线路':'选择'}</span></button>`).join('')}</div><p class="hint muted">线路切换为交互演示，暂未接入播放源；本机视频不受影响。</p>`),top:()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}),menu:()=>$('.dropdown').classList.toggle('open'),login,close:()=>$('#modal').close(),vip:()=>openModal('<h2>VIP 会员</h2><p class="muted">当前复刻页面尚未接入会员服务。</p><p class="hint">可直接浏览影片信息并使用本机收藏。会员开通与支付暂不可用。</p>'),history:()=>setHistoryOpen(true),favorite:addMovieFavorite,like:addMovieLike,dislike:()=>{const b=$('[data-action=dislike]');b.classList.toggle('active');$('[data-action=like]').classList.remove('active')},share:showShareCard,'copy-share':copyShareLink,feedback:showFeedback,play,episodes:()=>$('#episodes').scrollIntoView({behavior:'smooth'}),'prev-episode':()=>setEpisode(episode-1),'next-episode':()=>setEpisode(episode+1),fullscreen:()=>$('#player').requestFullscreen?.().catch(()=>toast('当前环境不支持全屏')),'expand-description':()=>{const p=$('.description');p.classList.toggle('expanded');$('[data-action=expand-description]').textContent=p.classList.contains('expanded')?'收起简介⌃':'展开简介⌄'},'toggle-episodes':()=>{const g=$('.episode-grid'),b=$('[data-action=toggle-episodes]');const expanded=g.classList.toggle('expanded');b.setAttribute('aria-expanded',String(expanded));b.textContent=expanded?'收起选集 ⌃':'展开全部 ⌄'},'reverse-episodes':()=>{const g=$('.episode-grid');[...g.children].reverse().forEach(e=>g.append(e))},'reset-filters':()=>{const query=listState.q;listState={cat:'',tag:'',area:'',language:'',year:'',status:'',sort:'',q:query,page:1};updateFilter()},'clear-history':()=>{save('history',[]);mine('/mine/history');toast('观看记录已清空')}};
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('/')&&!e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.getAttribute('href'));return}const b=e.target.closest('button');if(!b)return;if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.fav){const f=read('favorites'),id=b.dataset.fav,has=f.includes(id);save('favorites',has?f.filter(x=>x!==id):[...f,id]);b.textContent=has?'☆ 收藏':'★ 已收藏';toast(has?'已取消收藏':'已加入我的收藏');return}if(b.dataset.slide!==undefined){slide(+b.dataset.slide);clearInterval(heroTimer)}if(b.dataset.heroStep){clearInterval(heroTimer);slide(heroIndex+ +b.dataset.heroStep)}if(b.dataset.row){const row=$('#row-'+b.dataset.row);row.scrollBy({left:row.clientWidth*+b.dataset.step,behavior:'smooth'})}if(b.dataset.filter){listState[b.dataset.filter]=b.dataset.value;listState.page=1;updateFilter()}if(b.dataset.page){listState.page=+b.dataset.page;updateFilter();window.scrollTo({top:250,behavior:'smooth'})}if(b.dataset.rank)rank(b.dataset.rank);if(b.dataset.rankPeriod)rank(rankState.cat,b.dataset.rankPeriod);if(b.dataset.rankPage){rank(rankState.cat,rankState.period,+b.dataset.rankPage);$('.rank-filters').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}if(b.dataset.episode)setEpisode(+b.dataset.episode)});
document.addEventListener('keydown',e=>{if(!e.target.closest('.hero-thumbs')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();clearInterval(heroTimer);slide(e.key==='Home'?0:e.key==='End'?catalog.banners.length-1:heroIndex+(e.key==='ArrowRight'?1:-1));document.querySelector(`[data-slide="${heroIndex}"]`)?.focus({preventScroll:true})});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.matches('.search-form')){const q=new FormData(e.target).get('q').trim();if(q){e.target.querySelector('input').blur();navigate('/search?q='+encodeURIComponent(q))}else toast('请输入片名或演员')}if(e.target.id==='login-form'){submitAuthDemo(e.target)}if(e.target.id==='feedback-form'){submitFeedback(e.target)}});
document.addEventListener('change',e=>{if(e.target.id==='local-video'&&e.target.files[0]){if(localVideo)URL.revokeObjectURL(localVideo);localVideo=URL.createObjectURL(e.target.files[0]);attachVideo($('#player'),localVideo,toast)}if(e.target.id==='speed'&&$('video'))$('video').playbackRate=+e.target.value});
window.addEventListener('popstate',route);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
try{const response=await fetch('/catalog.json');if(!response.ok)throw Error('catalog');catalog=await response.json();const all=catalog.home_recommends.flatMap(s=>s.items).concat(catalog.sections.flatMap(s=>s.items),catalog.extraMovies||[]);const map=new Map();for(const m of all){m.duration=m.duration||'暂无集数';m.tags=m.tags||[];m.category=typeof m.category==='object'?m.category.name:m.category;if(!map.has(m.name))map.set(m.name,m)}movies=[...map.values()];for(const b of catalog.banners){const m=movies.find(m=>m.name===b.name||m.name.replace('来','來')===b.name);if(m&&b.link.startsWith('/movie/detail/')){const full=b.link.split('/').pop();m.id=full.split('-').pop();m.slug=full.slice(0,full.lastIndexOf('-'))}}seedHistoryDemo();route()}catch(e){$('#app').innerHTML='<div class="empty"><h1>影片资料加载失败</h1><p>请检查网络后刷新页面。</p><button class="primary" onclick="location.reload()">重新加载</button></div>';console.error(e)}

function themePage(path){const t=catalog.themeDetails?.find(t=>path.endsWith(t.id));if(!t){listing();return}document.title=t.name+' - SA影视';$('#app').innerHTML=`<section class="theme-hero"><img src="${t.bg_img}" alt="${esc(t.name)}"></section><div class="page"><h1>${esc(t.name)}</h1><p class="theme-description">${esc(t.description)}</p>${t.blocks.map((block,i)=>section({...block,items:block.items.map(m=>movies.find(x=>x.name===m.name)||m)},'theme-'+i)).join('')}</div>`}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();document.modelContext.registerTool({name:'search_films',title:'搜索影片',description:'在当前片库中搜索片名或演员，打开搜索结果页面。',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||!input.query.trim())throw new Error('请输入搜索词');const query=input.query.trim();navigate('/search?q='+encodeURIComponent(query));return {query,results:movies.filter(m=>[m.name,m.actor,m.director].some(v=>v?.includes(query))).map(m=>({id:m.id,name:m.name})).slice(0,30)}}},{signal:lifecycle.signal});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}

function positionHoverPreview(e){const card=e.target.closest?.(':is(.movie-grid,.feature-track) .movie-card');if(!card||card.contains(e.relatedTarget))return;const rect=card.getBoundingClientRect(),width=Math.min(288,Math.max(240,rect.width+48)),left=rect.left+(rect.width-width)/2;const bounded=Math.max(12,Math.min(left,window.innerWidth-width-12));card.style.setProperty('--hover-offset',(bounded-left)+'px');card.style.setProperty('--preview-left',(rect.left+rect.width/2)+'px');card.style.setProperty('--preview-top',(rect.top-10)+'px');card.style.setProperty('--preview-width',width+'px')}
document.addEventListener('pointerover',positionHoverPreview);
document.addEventListener('focusin',positionHoverPreview);

// Keep fixed carousel previews anchored during page and carousel scrolling.
document.addEventListener('scroll',()=>{document.querySelectorAll('.feature-track .movie-card:is(:hover,:focus-within)').forEach(card=>positionHoverPreview({target:card,relatedTarget:null}))},true);
window.addEventListener('resize',()=>{document.querySelectorAll('.feature-track .movie-card:is(:hover,:focus-within)').forEach(card=>positionHoverPreview({target:card,relatedTarget:null}))});

function seedHistoryDemo(){
 if(localStorage.getItem('sa-history-demo-seeded'))return;
 const existing=read('history');
 const demo=movies.filter(m=>!existing.some(x=>x.id===m.id)).slice(0,8).map((m,i)=>({id:m.id,episode:Math.min(i+1,+(m.duration.match(/\d+/)?.[0]||1)),date:new Date(Date.now()-i*3600000).toISOString(),demo:true}));
 save('history',[...existing,...demo].slice(0,80));
 localStorage.setItem('sa-history-demo-seeded','1');
}
function renderHistoryDrawer(){
 const panel=$('#history-drawer');if(!panel)return;
 const entries=read('history').map(h=>({h,m:movies.find(m=>m.id===h.id)})).filter(x=>x.m);
 panel.innerHTML=`<div class="history-drawer-head"><h3>最近观看</h3><span>${entries.length} 条记录</span></div>${entries.length?`<div class="history-scroll" tabindex="0" aria-label="观看记录，可上下滚动">${entries.map(({h,m})=>`<a class="history-entry" href="${movieUrl(m)}?episode=${Math.max(1,+h.episode||1)}"><img src="${m.img}" alt=""><span class="history-entry-copy"><span class="history-entry-title">${esc(m.name)}</span><span class="history-entry-meta">看到第 ${Math.max(1,+h.episode||1)} 集${h.demo?' · 模拟记录':''}</span></span><span class="history-entry-play">继续看 ›</span></a>`).join('')}</div>`:'<p class="history-drawer-empty">暂无观看记录，去发现喜欢的影片吧</p>'}<a class="history-drawer-footer" href="/mine/history">查看全部观看记录 ›</a>`;
}
function setHistoryOpen(open){const button=$('.history-menu .history'),panel=$('#history-drawer');if(!button||!panel)return;if(open&&panel.hidden)renderHistoryDrawer();panel.hidden=!open;button.setAttribute('aria-expanded',String(open));}
document.addEventListener('pointerover',e=>{const menu=e.target.closest?.('.history-menu');if(menu&&!menu.contains(e.relatedTarget))setHistoryOpen(true)});
document.addEventListener('pointerout',e=>{const menu=e.target.closest?.('.history-menu');if(menu&&!menu.contains(e.relatedTarget)&&!menu.contains(document.activeElement))setHistoryOpen(false)});
document.addEventListener('focusin',e=>{if(e.target.closest?.('.history-menu'))setHistoryOpen(true)});
document.addEventListener('focusout',e=>{const menu=e.target.closest?.('.history-menu');if(menu&&!menu.contains(e.relatedTarget))setHistoryOpen(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')setHistoryOpen(false)});
document.addEventListener('click',e=>{if(!e.target.closest?.('.history-menu'))setHistoryOpen(false)});

function playerControls(){return `<div class="transport"><div class="jump-row"><div class="jump-group"><button data-seek="-900" aria-label="后退15分钟">≪ 15m</button><button data-seek="-15" aria-label="后退15秒">‹ 15S</button></div><div class="jump-group"><button data-seek="15" aria-label="前进15秒">15S ›</button><button data-seek="900" aria-label="前进15分钟">15m ≫</button></div></div><div class="transport-row"><button class="round" data-seek="-15" aria-label="后退15秒">${transportIcon("back")}</button><button class="round" data-action="play" aria-label="播放" data-transport-play>${transportIcon("play")}</button><button class="round" data-seek="15" aria-label="前进15秒">${transportIcon("forward")}</button><input class="seek-range" type="range" min="0" max="100" value="0" step="0.1" aria-label="播放进度" disabled><span class="remaining">−00:00</span><select class="transport-speed" aria-label="播放速度"><option value="0.5">0.5X</option><option value="0.75">0.75X</option><option value="1" selected>1.0X</option><option value="1.25">1.25X</option><option value="1.5">1.5X</option><option value="2">2.0X</option></select><div class="volume-control"><div class="volume-popover" id="volume-popover" hidden><output class="volume-value">50</output><input class="volume-range" type="range" min="0" max="100" value="50" step="1" aria-label="音量" aria-valuetext="50%" style="--volume:50%"></div><button class="round" data-volume-toggle aria-label="调整音量" aria-expanded="false" aria-controls="volume-popover">${transportIcon("volume")}</button></div><button class="round" data-player-fullscreen aria-label="全屏">${transportIcon("full")}</button></div></div>`}
const format=s=>{s=Math.max(0,Math.floor(s||0));const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return (h?h+':':'')+String(m).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};
function attachVideo(player,url,toast){
 player.querySelector('video')?.remove();player.querySelector('.player-message').hidden=true;
 const video=document.createElement('video');video.className='video-source';video.playsInline=true;video.src=url;player.prepend(video);
 const sync=()=>{const range=player.querySelector('.seek-range'),valid=Number.isFinite(video.duration)&&video.duration>0;range.disabled=!valid;range.max=valid?video.duration:100;range.value=video.currentTime;range.style.setProperty('--progress',valid?100*video.currentTime/video.duration+'%':'0%');range.setAttribute('aria-valuetext',format(video.currentTime)+' / '+format(video.duration));player.querySelector('.remaining').textContent='−'+format(valid?video.duration-video.currentTime:0);const play=player.querySelector('[data-transport-play]');play.innerHTML=transportIcon(video.paused?'play':'pause');play.setAttribute('aria-label',video.paused?'播放':'暂停');updateVolumeUI(player,video.muted?0:Math.round(video.volume*100));};
 for(const event of ['loadedmetadata','durationchange','timeupdate','play','pause','ended','volumechange'])video.addEventListener(event,sync);
 video.volume=+player.querySelector('.volume-range').value/100;video.playbackRate=+player.querySelector('.transport-speed').value;video.addEventListener('error',()=>toast('浏览器无法播放此格式，请选择 MP4 或 WebM'));video.play().catch(()=>{});sync();
}
document.addEventListener('click',async e=>{const button=e.target.closest('.transport button');if(!button)return;const player=button.closest('.player'),video=player.querySelector('video');if(button.hasAttribute('data-player-fullscreen')){try{document.fullscreenElement?await document.exitFullscreen():await player.requestFullscreen()}catch{}return}if(!video)return;if(button.dataset.seek){if(Number.isFinite(video.duration))video.currentTime=Math.max(0,Math.min(video.duration,video.currentTime+Number(button.dataset.seek)))}});
document.addEventListener('input',e=>{if(!e.target.matches('.seek-range'))return;const video=e.target.closest('.player').querySelector('video');if(video&&Number.isFinite(video.duration))video.currentTime=+e.target.value;});
document.addEventListener('change',e=>{if(!e.target.matches('.transport-speed'))return;const video=e.target.closest('.player').querySelector('video');if(video)video.playbackRate=+e.target.value;});

function transportIcon(name){const paths={play:'<path d="m8 5 12 7-12 7z" fill="currentColor" stroke="none"/>',pause:'<path d="M8 5v14M16 5v14" stroke-width="4"/>',back:'<path d="m12 6-8 6 8 6zm8 0-8 6 8 6z" fill="currentColor" stroke="none"/>',forward:'<path d="m4 6 8 6-8 6zm8 0 8 6-8 6z" fill="currentColor" stroke="none"/>',volume:'<path d="M4 9h4l5-4v14l-5-4H4z" fill="currentColor"/><path d="M16 8q4 4 0 8m3-11q7 7 0 14"/>',muted:'<path d="M4 9h4l5-4v14l-5-4H4z" fill="currentColor"/><path d="m17 9 5 6m0-6-5 6M3 3l18 18"/>',full:'<path d="M9 4H4v5m11-5h5v5M4 15v5h5m6 0h5v-5M4 4l6 6m10-6-6 6m-4 4-6 6m10-6 6 6"/>'};return '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>'}

document.addEventListener("click",e=>{const b=e.target.closest("[data-line]");if(!b)return;selectedLine=Number(b.dataset.line);const label=$(".line-label");if(label)label.textContent="线路 "+selectedLine;$("#modal").close();toast("已选择线路 "+selectedLine+"（模拟线路）")});

function movieLikes(id){const entry=read('like-counts').find(x=>x.id===id);return entry&&Number.isSafeInteger(entry.count)&&entry.count>=0?entry.count:1280}
function likeButton(m){return `<button data-action="like" class="animated-like" aria-label="点赞，当前 ${movieLikes(m.id)} 赞"><span class="heart-mark" aria-hidden="true"><svg class="heart-outline" viewBox="0 0 24 24"><path d="M17.5,1.917a6.4,6.4,0,0,0-5.5,3.3,6.4,6.4,0,0,0-5.5-3.3A6.8,6.8,0,0,0,0,8.967c0,4.547,4.786,9.513,8.8,12.88a4.974,4.974,0,0,0,6.4,0C19.214,18.48,24,13.514,24,8.967A6.8,6.8,0,0,0,17.5,1.917Zm-3.585,18.4a2.973,2.973,0,0,1-3.83,0C4.947,16.006,2,11.87,2,8.967a4.8,4.8,0,0,1,4.5-5.05A4.8,4.8,0,0,1,11,8.967a1,1,0,0,0,2,0,4.8,4.8,0,0,1,4.5-5.05A4.8,4.8,0,0,1,22,8.967C22,11.87,19.053,16.006,13.915,20.313Z"/></svg><svg class="heart-filled" viewBox="0 0 24 24"><path d="M17.5,1.917a6.4,6.4,0,0,0-5.5,3.3,6.4,6.4,0,0,0-5.5-3.3A6.8,6.8,0,0,0,0,8.967c0,4.547,4.786,9.513,8.8,12.88a4.974,4.974,0,0,0,6.4,0C19.214,18.48,24,13.514,24,8.967A6.8,6.8,0,0,0,17.5,1.917Z"/></svg><svg class="heart-celebrate" viewBox="0 0 100 100"><path d="m10 10 10 10M10 50h10m0 30 10-10m60-60-10 10m10 30H80m0 30L70 70"/></svg></span><span>赞</span><span class="like-count" aria-live="polite" aria-atomic="true">${movieLikes(m.id).toLocaleString('en-US')}</span><span class="like-plus" aria-hidden="true">+1</span></button>`}
function addMovieLike(){if(!currentMovie)return;const id=currentMovie.id,count=movieLikes(id)+1;save('like-counts',[...read('like-counts').filter(x=>x.id!==id),{id,count}]);const b=$('[data-action=like]');b.classList.add('active');$('[data-action=dislike]').classList.remove('active');b.querySelector('.like-count').textContent=count.toLocaleString('en-US');b.setAttribute('aria-label','点赞，当前 '+count+' 赞');b.classList.remove('celebrating');void b.offsetWidth;b.classList.add('celebrating')}

function favoriteCount(id){const entry=read('favorite-counts').find(x=>x.id===id);return entry&&Number.isSafeInteger(entry.count)&&entry.count>=0?entry.count:368}
function favoriteButton(m){const saved=read('favorites').includes(m.id);return `<button data-action="favorite" class="animated-favorite ${saved?'active':''}" aria-label="收藏，当前 ${favoriteCount(m.id)} 次"><svg class="bookmark-icon" viewBox="0 0 24 24" aria-hidden="true"><path class="bookmark-back" d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/><path class="bookmark-check" d="M8 11l3 3 5-5"/></svg><span class="favorite-label">${saved?'已收藏':'收藏'}</span><span class="favorite-count" aria-live="polite" aria-atomic="true">${favoriteCount(m.id).toLocaleString('en-US')}</span><span class="favorite-plus" aria-hidden="true">+1</span></button>`}
function addMovieFavorite(){if(!currentMovie)return;const id=currentMovie.id,favorites=read('favorites'),saved=favorites.includes(id),count=Math.max(0,favoriteCount(id)+(saved?-1:1));save('favorites',saved?favorites.filter(x=>x!==id):[...favorites,id]);save('favorite-counts',[...read('favorite-counts').filter(x=>x.id!==id),{id,count}]);const b=$('[data-action=favorite]');b.classList.toggle('active',!saved);b.querySelector('.favorite-label').textContent=saved?'收藏':'已收藏';b.querySelector('.favorite-count').textContent=count.toLocaleString('en-US');b.querySelector('.favorite-plus').textContent=saved?'−1':'+1';b.setAttribute('aria-label',(saved?'收藏':'取消收藏')+'，当前 '+count+' 次');b.classList.remove('celebrating');void b.offsetWidth;b.classList.add('celebrating');toast(saved?'已取消收藏':'已加入我的收藏')}

function showShareCard(){if(!currentMovie)return;const m=currentMovie,text=`我正在SA影视看《${m.name}》，快来和我一起看吧！`,url=location.href;const links={facebook:'https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(url),x:'https://twitter.com/intent/tweet?text='+encodeURIComponent(text)+'&url='+encodeURIComponent(url),telegram:'https://t.me/share/url?url='+encodeURIComponent(url)+'&text='+encodeURIComponent(text)};openModal(`<section class="share-card" aria-label="分享影片"><div class="share-summary"><img class="share-poster" src="${esc(m.img)}" alt="${esc(m.name)}"><div class="share-copy"><h2>${esc(m.name)}</h2><p class="share-stats">${contentTags(m)}<strong>🔥 ${esc(m.heat||'暂无热度')}</strong><strong>${esc(m.score)} <small>分</small></strong></p><p class="share-message">${esc(text)}</p></div></div><div class="share-platforms"><a class="share-platform facebook" href="${esc(links.facebook)}" target="_blank" rel="noopener noreferrer" aria-label="分享到 Facebook" title="分享到 Facebook"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M14 22v-9h3l.5-4H14V7c0-1 .3-2 2-2h2V1.5A24 24 0 0 0 15 1c-3 0-5 2-5 5v3H7v4h3v9z"/></svg></a><a class="share-platform x" href="${esc(links.x)}" target="_blank" rel="noopener noreferrer" aria-label="分享到 X" title="分享到 X"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3h5l13 18h-5zM21 3 3 21" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></a><a class="share-platform telegram" href="${esc(links.telegram)}" target="_blank" rel="noopener noreferrer" aria-label="分享到 Telegram" title="分享到 Telegram"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M21 3 2 10c-1 .4-1 .9 0 1.2l5 1.6 2 6c.2.6.5.6.8.3l3-3 5 3.7c.8.5 1.3.2 1.5-.7L22 4c.2-1-.2-1.3-1-1zM8 12l10-6-8 8-.5 3z"/></svg></a><button class="share-platform copy-link" data-action="copy-share" aria-label="复制分享链接" title="复制链接"><svg viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="m10 8 3-3a4 4 0 0 1 6 6l-3 3M14 16l-3 3a4 4 0 0 1-6-6l3-3M8 16l8-8"/></g></svg></button></div><div class="share-link-fallback" hidden><label>分享链接<input readonly aria-label="分享链接" value="${esc(url)}"></label><p>请复制上方链接</p></div></section>`)}
async function copyShareLink(){try{await navigator.clipboard.writeText(location.href);toast('链接已复制')}catch{const box=$('.share-link-fallback');if(box){box.hidden=false;box.querySelector('input').select()}}}

function showFeedback(){const issues=[['视频卡顿','播放过程中频繁停顿','M19 7a8 8 0 1 0 1 7M19 3v4h-4'],['无法播放','视频无法正常启动','M3 3l18 18M4 7v10h12V7H4m12 3 5-3v10l-5-3'],['音画不同步','声音与画面存在延迟','M3 10v4m4-8v12m5-15v18m5-15v12m4-8v4'],['视频闪退','播放时突然退出或崩溃','m13 2-9 12h7l-1 8 10-13h-7z'],['黑屏','画面全黑但音频正常','M3 4h18v13H3zM12 17v4m-5 0h10'],['其他问题','描述你遇到的其他问题','M3 4h18v13H8l-5 4z']];openModal(`<section class="feedback-panel"><header><span class="feedback-dot"></span>用户反馈</header><h2>遇到了什么问题？</h2><p class="feedback-intro">选择问题即可提交，其他问题可补充说明。</p><form id="feedback-form"><fieldset class="feedback-options"><legend class="sr-only">问题类型</legend>${issues.map(([name,desc,path])=>`<label class="feedback-choice"><input type="radio" name="issue" value="${name}" required><span class="feedback-choice-body"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg><strong>${name}</strong><small>${desc}</small></span></label>`).join('')}</fieldset><div class="feedback-description" hidden><textarea name="feedback" maxlength="100" rows="5" aria-label="补充问题描述" placeholder="请描述遇到的问题"></textarea><span class="feedback-counter"><span id="feedback-count">0</span>/100</span></div><p class="feedback-local-note">反馈暂存于当前浏览器，尚未接入客服服务。</p><button type="submit" class="primary feedback-submit" hidden disabled>提交反馈</button><p class="feedback-result" role="status" hidden></p></form></section>`)}
function submitFeedback(form){const data=new FormData(form),issue=data.get('issue'),description=issue==='其他问题'?String(data.get('feedback')||'').trim():'';if(!issue){form.reportValidity();return}if(issue==='其他问题'&&!description){const input=form.querySelector('textarea');input.setCustomValidity('请补充你遇到的问题');input.reportValidity();return}const records=read('feedback-records');save('feedback-records',[{movieId:currentMovie?.id,issue,description,line:selectedLine,episode,date:new Date().toISOString()},...records].slice(0,50));$('#modal').close();toast('已提交，感谢您的反馈');const node=$('#toast');node.classList.add('feedback-success');node.innerHTML='<span class="feedback-success-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="currentColor"/><path d="m7 12 3 3 7-7" fill="none" stroke="#174737" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span>已提交，感谢您的反馈</span>';}
document.addEventListener('input',e=>{if(!e.target.matches('#feedback-form textarea'))return;e.target.setCustomValidity('');$('#feedback-count').textContent=e.target.value.length;e.target.closest('form').querySelector('.feedback-submit').disabled=!e.target.value.trim();});

document.addEventListener('change',e=>{if(e.target.matches('#feedback-form input[name=issue]')){const form=$('#feedback-form'),other=e.target.value==='其他问题';form.querySelector('textarea').setCustomValidity('');form.querySelector('.feedback-description').hidden=!other;form.querySelector('.feedback-submit').hidden=!other;form.querySelector('.feedback-submit').disabled=!form.querySelector('textarea').value.trim();if(other)form.querySelector('textarea').focus();else submitFeedback(form)}});

function updateVolumeUI(player,value){const range=player.querySelector('.volume-range');range.value=value;range.style.setProperty('--volume',value+'%');range.setAttribute('aria-valuetext',value+'%');player.querySelector('.volume-value').textContent=value;player.querySelector('[data-volume-toggle]').innerHTML=transportIcon(value===0?'muted':'volume')}
function closeVolume(){const panel=$('.volume-popover');if(panel){panel.hidden=true;$('[data-volume-toggle]').setAttribute('aria-expanded','false')}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-volume-toggle]');if(button){const panel=button.closest('.volume-control').querySelector('.volume-popover');panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));return}if(!e.target.closest('.volume-control'))closeVolume()});
document.addEventListener('input',e=>{if(!e.target.matches('.volume-range'))return;const player=e.target.closest('.player'),value=Number(e.target.value),video=player.querySelector('video');updateVolumeUI(player,value);if(video){video.volume=value/100;video.muted=value===0}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target.closest('.volume-control')){closeVolume();$('[data-volume-toggle]').focus()}});

document.addEventListener('click',e=>{const button=e.target.closest('[data-close-ad]');if(button)button.closest('.left-ad').remove()});

function submitAuthDemo(form){if(form.dataset.busy==='true')return;syncAuthForm(form);const button=form.querySelector('.auth-submit');if(button.disabled||!form.reportValidity())return;const account=form.querySelector('[name=account]').value.trim(),register=form.dataset.mode==='register';form.dataset.busy='true';button.disabled=true;button.textContent=register?'注册中…':'登录中…';form.querySelectorAll('input').forEach(input=>input.disabled=true);setTimeout(()=>{if(!form.isConnected||!$('#modal').open)return;form.querySelectorAll('input[type=password],input[name=password],input[name=confirm]').forEach(input=>input.value='');if(register){demoRegisteredAccounts.add(account.toLowerCase());login();$('#auth-account').value=account;toast('演示注册成功，请登录')}else{demoAccount=account;$('#modal').close();navigate('/mine/favorites');toast('登录成功')}},400)}
document.addEventListener('click',e=>{if(e.target.closest('[data-auth-logout]')){demoAccount='';$('#modal').close();navigate('/');toast('已退出登录')}});

function getSearchHistory(){if(searchHistoryCache)return searchHistoryCache;try{const raw=localStorage.getItem('sa-search-history');const data=raw===null?['兰香如故','藏海花','凡人修仙传','哪吒之魔童闹海','重器']:JSON.parse(raw);searchHistoryCache=Array.isArray(data)?[...new Set(data.filter(x=>typeof x==='string'&&x.trim()))].slice(0,5):[]}catch{searchHistoryCache=[]}return searchHistoryCache}
function persistSearchHistory(items){searchHistoryCache=items;try{save('search-history',items)}catch{}}
function rememberSearch(query){const q=String(query||'').trim();if(q)persistSearchHistory([q,...getSearchHistory().filter(x=>x!==q)].slice(0,5))}
function searchDrawer(){const items=getSearchHistory();return `<section class="search-history-section" aria-label="历史搜索"><div class="search-drawer-heading"><h3>历史搜索</h3>${items.length?'<button type="button" data-search-clear>清空</button>':''}</div><div class="search-history-list">${items.length?items.map((q,i)=>`<div class="search-history-row"><a href="/search?q=${encodeURIComponent(q)}"><span>${esc(q)}</span></a><button type="button" data-search-delete="${i}" aria-label="删除搜索记录：${esc(q)}">×</button></div>`).join(''):'<p class="search-history-empty">暂无搜索记录</p>'}</div></section><section class="search-popular" aria-label="热门搜索"><h3>热门搜索</h3>${['醒来','交锋','重器','凡人修仙传','哪吒之魔童闹海'].map((q,i)=>`<a href="/search?q=${encodeURIComponent(q)}"><span class="search-rank">${i+1}</span>${esc(q)}</a>`).join('')}</section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-search-delete],[data-search-clear]');if(!b)return;const items=getSearchHistory();persistSearchHistory(b.hasAttribute('data-search-clear')?[]:items.filter((_,i)=>i!==Number(b.dataset.searchDelete)));const drawer=b.closest('.search-suggest');drawer.innerHTML=searchDrawer();const next=drawer.querySelector('[data-search-delete]')||drawer.closest('form').querySelector('input');next.focus()});
